def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_op = op[-1]

    # Counts
    op_c = 0
    for x in op:
        if x == 'C':
            op_c += 1
    op_d = n - op_c
    my_d = 0
    for x in my:
        if x == 'D':
            my_d += 1

    # Recent windows
    w = history[-12:] if n >= 12 else history
    w_op_c = 0
    for h in w:
        if h[1] == 'C':
            w_op_c += 1
    w_len = len(w)
    w_op_d = w_len - w_op_c

    # Consecutive opponent defections
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            consec_d += 1
        else:
            break

    # Consecutive opponent cooperations
    consec_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            consec_c += 1
        else:
            break

    # ---- Endgame: final rounds, exploit confirmed cooperators ----
    if n >= 96:
        if op_d <= 1 and my_d <= 1:
            # mutual cooperation was great; defect at most final 2 rounds
            if n >= 98:
                return 'D'
            return 'C'
        if consec_d >= 2:
            return 'D'
        if last_op == 'D':
            return 'D'
        if op_d * 2 < n and n >= 97:
            return 'D'
        return 'C'

    if n >= 88:
        if op_d <= 2:
            if n >= 94:
                return 'D'
            return 'C'
        if consec_d >= 3:
            return 'D'
        if w_op_d >= 4:
            return 'D'
        return 'C'

    # ---- Early game: cooperative opening with light probing ----
    if n < 6:
        return 'C'

    # ---- Clear always-defector: punish, rare probe ----
    if op_d >= n - 1 and n >= 8:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # ---- High defection rate: defect mostly ----
    if op_d * 5 >= n * 3:
        if consec_d >= 2:
            return 'D'
        if w_op_d >= 5:
            return 'D'
        if n % 9 == 0:
            return 'C'
        return 'D'

    # ---- Strongly cooperative opponent: harvest with moderated probing ----
    if op_d == 0:
        # Opponent never defected. Exploit more as trust builds.
        if n < 12:
            return 'C'
        if n >= 70:
            # Late: defect more often
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        if n >= 40:
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        if n >= 20:
            if rng.random() < 0.08:
                return 'D'
            return 'C'
        return 'C'

    # ---- Opponent has defected occasionally ----
    # If opponent punished our defections consistently, stay cooperative.
    if last_my == 'D' and last_op == 'D' and consec_d >= 2:
        # we were likely retaliated against; return to cooperation
        if op_d * 4 < n * 3:
            return 'C'

    # Opponent just defected
    if last_op == 'D':
        # forgive if opponent overwhelmingly cooperative
        if op_d * 6 <= n and consec_d <= 1:
            return 'C'
        if op_d * 4 <= n and consec_d <= 2:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        # otherwise retaliate
        return 'D'

    # Opponent just cooperated
    # If opponent mostly cooperates, cooperate but probe when safe
    if op_d * 4 <= n:
        if n >= 30 and n % 15 == 0 and op_d * 8 <= n:
            return 'D'
        return 'C'

    if op_d * 2 <= n:
        # moderate: tit-for-tat with occasional forgiveness already covered
        if consec_c >= 4 and n >= 25 and n % 19 == 0:
            return 'D'
        return 'C'

    # Opponent defected roughly half or more but last was C: cautious cooperate
    if w_op_d * 2 < w_len:
        return 'C'
    return 'D'
